{
  "probability": 0.77,
  "range_low": 0.65,
  "range_high": 0.89,
  "summary": [
    "Forecasts are mixed but point to a plausible path to a constitutional 2/3 majority primarily via a Fidesz-TISZA coalition.",
    "TISZA polling gains in several surveys raise the probability of opposition-led aggregation crossing 133 seats if translated into seats.",
    "Historical base rates show 2/3 majorities have occurred in Hungary under similar rules, yet polling dispersion, fragmentation, and turnout uncertainty temper confidence.",
    "Markets and polls diverge on the outcome, keeping a cautious, calibrated view rather than a high-confidence single-party win."
  ],
  "confidence": "high",
  "narrative": "Using a reference-class anchor from Hungary’s history of 2/3 majorities and incorporating updates from current polls and coalition dynamics, the posterior probability remains substantial but not certainty. The strongest upward pressure comes from potential Fidesz-TISZA coalition viability and polling momentum, while fragmentation and turnout uncertainty provide down/neutral counterweights.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "Reference class: Hungarian parliamentary history with constitutional 2/3 majorities (133+ seats) under post-1990 rules. Anchor probability selected to reflect a modest base rate given current uncertainty and the possibility of coalition pathways."
    },
    "factor_updates": [
      {
        "factor": "Coalition viability: Fidesz and TISZA forming a unified bloc to reach 2/3",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A post-election Fidesz+TISZA coalition could plausibly reach well above 133 seats (e.g., 177 seats per PolitPro projection) if such a coalition materializes."
      },
      {
        "factor": "TISZA polling surge relative to Fidesz",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Recent polls place TISZA ahead or closely competitive with Fidesz, increasing the probability of coalition-led 2/3 outcomes or cross-threshold seat totals."
      },
      {
        "factor": "Opposition unity progress (parties quitting to back TISZA)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Financial Times reporting of opposition consolidation around TISZA raises the chance of a durable anti-Orbán coalition achieving 133+ seats."
      },
      {
        "factor": "Poll volatility/divergence and betting market uncertainty",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Divergent polls and mixed market signals temper a clean calibration toward a guaranteed 2/3 majority."
      },
      {
        "factor": "Third-party entrants crossing threshold affecting seat distribution",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Other parties entering the threshold could siphon votes and disrupt clear 2/3 outcomes."
      },
      {
        "factor": "Historical frequency of constitutional 2/3 majorities",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Past patterns show 2/3 majorities are not guaranteed; base-rate headwinds exist absent stable coalition translation of votes into seats."
      }
    ],
    "synthesis_rationale": "The posterior 0.77 reflects a synthesis where the strongest upward pressure comes from potential Fidesz-TISZA coalition viability and polling momentum, tempered by fragmentation, turnout uncertainty, and market skepticism. Calibration accounts for correlated factors and historical context to produce a calibrated but non-deterministic estimate."
  }
}

{
  "probability": 0.77,
  "range_low": 0.66,
  "range_high": 0.86,
  "summary": [
    "Coalition viability between Fidesz and TISZA could push the outcome toward a 2/3 majority if the coalition translates votes to seats.",
    "TISZA polling lead and opposition consolidation increase the likelihood of a 2/3 majority via coalition, though uncertainty remains due to polling dispersion and turnout effects.",
    "Historical base rate and electoral-system bias suggest a non-zero but not guaranteed probability; current signals are mixed but tilt upward toward a potential 2/3 if coalition forms."
  ],
  "confidence": "high",
  "narrative": "Starting from a historical base rate of about 44% for a 2/3 majority, current signals show meaningful upward pressure from a viable Fidesz-TISZA coalition and anti-Orbán unity. While polls are divergent and turnout could shift seat allocations, the posterior probability of a 2/3 outcome remains plausible and above baseline, consistent with the 77% posterior.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical frequency of constitutional two-thirds majorities (133+ seats) in Hungary since 1990; anchor chosen as the base rate before current electoral dynamics."
    },
    "factor_updates": [
      {
        "factor": "Coalition viability: Fidesz and TISZA forming a unified bloc to reach 2/3",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "If a durable Fidesz+TISZA coalition forms, estimated seat totals exceed 133 significantly (e.g., around 177 seats in some projections), supporting a 2/3 outcome."
      },
      {
        "factor": "TISZA polling surge relative to Fidesz",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Polls in early 2026 show TISZA gaining; a sustained lead increases coalition prospects and overall seat tallies toward 2/3 potential."
      },
      {
        "factor": "Opposition unity progress",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Consolidation behind TISZA could strengthen anti-Orbán bloc and raise odds of surpassing 133 seats if thresholds align with seat distribution."
      },
      {
        "factor": "Poll volatility and market uncertainty",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Divergent polls and market bets imply residual uncertainty, preventing over-commitment to a 2/3 path; this tempers the update."
      },
      {
        "factor": "Electoral-system bias favoring the largest bloc",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Hungary's electoral rules can amplify the lead of the dominant bloc, aiding an anti-Orbán coalition in reaching 133+ seats if cohesion holds."
      },
      {
        "factor": "Third-party entrants affecting seat distribution",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Other parties crossing thresholds could siphon votes from major blocs, complicating a 2/3 majority."
      }
    ],
    "synthesis_rationale": "We start from a 0.44 anchor reflecting historical base rate. Upward updates come from coalition viability, polling momentum, and anti-Orbán unity, amplified by the electoral-system bias, while downward pulls include poll volatility and third-party entrants. The combination yields a posterior around 0.77, acknowledging correlation among factors and residual uncertainty."
  }
}

